import java.util.*;
import java.io.*;
import java.math.*;

public class E {
    private static final BigInteger MOD = BigInteger.valueOf(998244353L);

    public static void main(String[] args) throws Exception {
        BufferedReader infile = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(infile.readLine());

        long N = Long.parseLong(st.nextToken());
        long M = Long.parseLong(st.nextToken());
        long L = Long.parseLong(st.nextToken());
        long R = Long.parseLong(st.nextToken());

        System.out.println(solve(N, M, L, R));
    }

    private static long solve(long N, long M, long L, long R) {
        long cells = N * M;
        long answer = modPow(R - L + 1, cells, MOD.longValue());

        if ((cells % 2L) == 1L) {
            return answer;
        }

        if (((R - L) % 2L) == 0L) {
            answer++;
        }

        return (answer * inverseTwo()) % MOD.longValue();
    }

    private static long modPow(long base, long exponent, long modulus) {
        return BigInteger.valueOf(base).modPow(BigInteger.valueOf(exponent), BigInteger.valueOf(modulus)).longValue();
    }

    private static long inverseTwo() {
        return BigInteger.valueOf(2).modPow(MOD.subtract(BigInteger.valueOf(2)), MOD).longValue();
    }
}
